components.content:
/* Carte principale - Sticky */
.sfc-card {
  position: sticky;
  top: 20px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 24px;
  font-family: 'Segoe UI', Roboto, sans-serif;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}
.sfc-card h3 {
  font-size: 18px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 4px;
}
.sfc-card .sfc-subtitle {
  font-size: 13.5px;
  color: #4b5563;
  margin: 0 0 18px;
  line-height: 1.5;
}
.sfc-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
  font-size: 13.5px;
  color: #374151;
  line-height: 1.5;
}
.sfc-row .sfc-ico {
  flex-shrink: 0;
  width: 20px;
  text-align: center;
  font-size: 15px;
  margin-top: 1px;
  color: #4b5563;
}
.sfc-row a {
  color: #3b82f6;
  text-decoration: none;
}
.sfc-row a:hover {
  text-decoration: underline;
}
.sfc-row strong {
  color: #111827;
  font-weight: 600;
}
.sfc-stitle {
  font-size: 16px;
  font-weight: 700;
  color: #111827;
  margin: 20px 0 12px;
  padding-top: 16px;
  border-top: 1px solid #e5e7eb;
}
.sfc-boxes {
  display: flex;
  gap: 10px;
  margin-bottom: 14px;
  width: 100%;
}
.sfc-box {
  flex: 1;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 12px;
}
.sfc-box .sfc-lbl {
  font-size: 11.5px;
  color: #6b7280;
  font-weight: 500;
  margin: 0 0 6px;
  line-height: 1.3;
}
.sfc-box .sfc-val {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  margin: 0;
}
.sfc-box .sfc-sub {
  font-size: 11px;
  color: #9ca3af;
  font-weight: 400;
}
.sfc-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #16a34a;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  margin-top: 5px;
}
.sfc-link:hover {
  text-decoration: underline;
}
.sfc-link-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
}
.correction-banner {
  background: #fef3cd;
  border: 1px solid #ffc107;
  border-radius: 12px;
  padding: 20px 24px;
  margin-bottom: 24px;
}
.correction-banner h2 {
  color: #856404;
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 8px;
}
.correction-banner p {
  color: #6c5c02;
  font-size: 14px;
  line-height: 1.6;
  margin: 0;
}
.delay-warning {
  background: #f8f9fa;
  border-left: 4px solid #dc3545;
  border-radius: 8px;
  padding: 16px 20px;
  margin-bottom: 24px;
}
.delay-warning p {
  color: #721c24;
  font-size: 14px;
  font-weight: 600;
  margin: 0;
}

actions.customAction:
const recapDiv = document.getElementById("recapDisplayRes");
if (!recapDiv) return;

let list_of_datagrid = [];
let data_stock = [];
const exclude = ["button", "file", "container", "panel"];
const excludeKeys = [
  "luEtApprouveRes",
  "startButtonRes",
  "stylesCssSidebarRessoumission",
  "stickyInjectorRes",
  "htmlRecapRes",
  "columns42Res",
  "precedent5Res",
  "next5Res",
  "confirmationCorrectionEligibilite",
  "confirmationDelai15Jours",
  "observationsCorrection",
  "infoCardsRes",
  "sidebarFournisseurRes",
  "colConfirmationRes",
  "mainLayoutRes",
  "htmlCorrectionBanner",
  "htmlDelayWarning",
  "htmlPiecesNoteRes",
  "htmlInfoPrefilledRes"
];
const includesLabelForSelect = ["libelle", "label", "Prefecture", "Commune", "nom", "nomCentre"];

function isObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function getDisplayValue(value) {
  if (value === null || value === undefined) return "";
  if (isObject(value)) {
    if (value.nom)        return value.nom;
    if (value.label)      return value.label;
    if (value.libelle)    return value.libelle;
    if (value.nomCentre)  return value.nomCentre;
    if (value.Prefecture) return value.Prefecture;
    if (value.Commune)    return value.Commune;
    const prop = includesLabelForSelect.find(p => value[p] !== undefined);
    if (prop) return String(value[prop]);
    return JSON.stringify(value).replace(/[{}"[\]]/g, "").replace(/,/g, ", ");
  }
  if (Array.isArray(value)) return value.join(", ");
  return String(value);
}

const selectLabelMap = {};
utils.eachComponent(
  form.components,
  (component, path) => {
    if (component.type === "select" && !excludeKeys.includes(component.key)) {
      const comp = instance.root.getComponent(component.key);
      if (comp && comp.selectOptions && comp.selectOptions.length > 0) {
        const currentValue = data[component.key];
        if (currentValue !== undefined && currentValue !== "" && currentValue !== null) {
          const strVal = JSON.stringify(currentValue);
          const match = comp.selectOptions.find(opt =>
            JSON.stringify(opt.value) === strVal ||
            String(opt.value) === String(currentValue)
          );
          if (match) selectLabelMap[component.key] = match.label;
        }
      }
    }
  },
  false
);

utils.eachComponent(
  form.components,
  (component, path) => {
    let splitted_path = path.split(".");
    let skip = false;

    if (
      !exclude.includes(component.type) &&
      !excludeKeys.includes(component.key) &&
      !component.hidden &&
      ![null, undefined, "", [], {}, "[]", "{}"].includes(data[component.key]) &&
      !["null", "undefined", "", "[]", "{}"].includes(JSON.stringify(data[component.key]))
    ) {
      if (component.type === "datagrid") {
        list_of_datagrid.push(component.key);
      } else {
        if (
          splitted_path.length >= 2 &&
          list_of_datagrid.includes(splitted_path[splitted_path.length - 2])
        ) {
          skip = true;
        }
      }
      if (!skip) {
        data_stock.push({
          key: component.key,
          label: component.label,
          value: data[component.key] || (component.type === "datagrid" ? [] : ""),
          type: component.type,
          components: component.components || "",
        });
      }
    }
  },
  false
);

const seenKeys = new Set();
data_stock = data_stock.filter(elmt => {
  if (seenKeys.has(elmt.key)) return false;
  seenKeys.add(elmt.key);
  return true;
});

let ourTable = `<style>
  .recap-container { width: 100%; margin: 0 auto; }
  .recap-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
  .recap-table thead th {
    background-color: #EEEEEE; color: black; font-weight: bold;
    padding: 10px; border: 2px solid #ccc; text-align: center;
    font-family: 'Segoe UI', Roboto, sans-serif; font-size: 15px;
  }
  .recap-table th, .recap-table td {
    border: 2px solid #ccc; padding: 8px; text-align: left;
    font-size: 14px; font-family: 'Segoe UI', Roboto, sans-serif; word-wrap: break-word;
  }
  .recap-table td:first-child { width: 5%; text-align: center; }
  .recap-table td:nth-child(2) { width: 40%; }
  .recap-table td:last-child { width: 55%; }
  .datagrid-title { font-weight: bold; background-color: #f5f5f5; }
</style>
<div class="recap-container">
<h3 style="color: #1a56db; margin-top: 0;">Récapitulatif de votre resoumission</h3>
<table class="recap-table">
  <thead>
    <tr><th>#</th><th>Champs du formulaire</th><th>Données saisies</th></tr>
  </thead>
  <tbody>`;

let index = 1;

data_stock.forEach((elmt) => {
  if (Array.isArray(elmt.value) && elmt.type === "datagrid" && elmt.value.length > 0) {
    ourTable += `<tr><td colspan="3" class="datagrid-title"><b>${elmt.label}</b></td></tr>`;
    elmt.value.forEach((rowData) => {
      Object.keys(rowData).forEach((key) => {
        let cmpnt = utils.getComponent(elmt.components, key);
        let formattedValue;
        if (key === "prefectureDuSite") {
          formattedValue = (rowData[key] && rowData[key].Prefecture) ? rowData[key].Prefecture : "Non spécifié";
        } else if (key === "communeDuSite") {
          formattedValue = (rowData[key] && rowData[key].Commune) ? rowData[key].Commune : "Non spécifié";
        } else if (isObject(rowData[key])) {
          formattedValue = getDisplayValue(rowData[key]);
        } else {
          formattedValue = rowData[key];
        }
        if (typeof formattedValue === "string" && /\d{4}-\d{2}-\d{2}T/.test(formattedValue)) {
          formattedValue = moment(formattedValue).format("DD/MM/YYYY");
        }
        if (formattedValue !== "") {
          ourTable += `<tr><td>${index++}</td><td>&nbsp;&nbsp;&nbsp;${cmpnt ? cmpnt.label : key}</td><td>${formattedValue}</td></tr>`;
        }
      });
    });
  } else if (elmt.type === "select") {
    if (elmt.value === undefined || elmt.value === "" || elmt.value === null) return;
    let valueToDisplay = "";
    if (selectLabelMap[elmt.key]) {
      valueToDisplay = selectLabelMap[elmt.key];
    } else if (isObject(elmt.value)) {
      valueToDisplay = getDisplayValue(elmt.value);
    } else if (Array.isArray(elmt.value)) {
      valueToDisplay = elmt.value.join(", ");
    } else {
      valueToDisplay = String(elmt.value);
    }
    if (!valueToDisplay) return;
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${valueToDisplay}</td></tr>`;
  } else if (elmt.type === "radio") {
    const radioComp = utils.getComponent(form.components, elmt.key);
    let radioLabel = elmt.value;
    if (radioComp && radioComp.values) {
      const match = radioComp.values.find(opt => opt.value === elmt.value);
      if (match) radioLabel = match.label;
    }
    if (radioLabel === elmt.value) {
      switch (elmt.value) {
        case "Oui":  radioLabel = "Oui"; break;
        case "Non":  radioLabel = "Non"; break;
        case "oui":  radioLabel = "OUI"; break;
        case "non":  radioLabel = "NON"; break;
        default:     radioLabel = String(elmt.value); break;
      }
    }
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${radioLabel}</td></tr>`;
  } else if (elmt.type === "day") {
    const dayVal = elmt.value && elmt.value !== "00/00/0000" ? elmt.value : "";
    if (!dayVal) return;
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${dayVal}</td></tr>`;
  } else if (elmt.type === "datetime") {
    const formatted = elmt.value ? moment(elmt.value).format("DD/MM/YYYY") : "";
    if (!formatted) return;
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${formatted}</td></tr>`;
  } else if (elmt.type === "checkbox") {
    const displayValue = elmt.value ? "Oui" : "Non";
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${displayValue}</td></tr>`;
  } else {
    let displayValue;
    switch (elmt.value) {
      case "renonciationNationalite": displayValue = "Renonciation à la nationalité togolaise"; break;
      case "reintegrationNationalite": displayValue = "Réintégration dans la nationalité togolaise"; break;
      default:
        displayValue = isObject(elmt.value) ? getDisplayValue(elmt.value) : String(elmt.value);
        break;
    }
    if (!displayValue || displayValue === "undefined" || displayValue === "null") return;
    ourTable += `<tr><td>${index++}</td><td><b>${elmt.label}</b></td><td>${displayValue}</td></tr>`;
  }
});

ourTable += `</tbody></table><hr></div>`;
recapDiv.textContent = '';
recapDiv.insertAdjacentHTML('beforeend', ourTable);
